# ── Generated by NNDL Code Generator `─────────────────────────────`
# Project   : MNIST CNN Demo
# Dataset   : mnist  (10 classes, input [1, 28, 28])
# Optimizer : adam  lr=0.001
# Loss      : cross_entropy
# Epochs    : 3  batch=64  val_split=0.1
# ──────────────────────────────────────────────────────────────────


import torch
import torch.nn as nn
import torch.optim as optim
from torch.utils.data import DataLoader, random_split
from torchvision import datasets, transforms



class Model(nn.Module):
    def __init__(self):
        super().__init__()
        self.net = nn.Sequential(
            nn.Conv2d(1, 16, kernel_size=(3, 3), stride=(1, 1), padding=(1, 1)),  # Conv1
            nn.ReLU(),  # ReLU1
            nn.MaxPool2d(kernel_size=(2, 2), stride=(2, 2), padding=(0, 0)),  # Pool1
            nn.Flatten(start_dim=1),  # Flatten
            nn.Linear(3136, 128, bias=True),  # FC1
            nn.ReLU(),  # ReLU2
            nn.Linear(128, 10, bias=True),  # Output
            nn.Softmax(dim=1),  # Softmax
        )

    def forward(self, x):
        return self.net(x)


def get_dataloaders(data_root: str = "./data"):
    transform = transforms.Compose([
        transforms.ToTensor(),
        transforms.Normalize(mean=(0.1307,), std=(0.3081,)),
    ])

    full_dataset = datasets.MNIST(root=data_root, train=True, download=True, transform=transform)

    val_size   = int(len(full_dataset) * 0.1)
    train_size = len(full_dataset) - val_size

    if val_size > 0:
        train_set, val_set = random_split(full_dataset, [train_size, val_size])
    else:
        train_set, val_set = full_dataset, None

    train_loader = DataLoader(train_set, batch_size=64, shuffle=True, num_workers=2, pin_memory=True)
    val_loader   = DataLoader(val_set,   batch_size=64, shuffle=False,    num_workers=2, pin_memory=True) if val_set else None

    return train_loader, val_loader


def build_optimizer_and_loss(model):
    optimizer = optim.Adam(model.parameters(), lr=0.001)
    criterion = nn.CrossEntropyLoss()
    return optimizer, criterion


def train_one_epoch(model, loader, optimizer, criterion, device):
    """One full pass over the training set. Returns average loss."""
    model.train()
    running_loss = 0.0

    for inputs, labels in loader:
        inputs, labels = inputs.to(device), labels.to(device)
        optimizer.zero_grad()
        outputs = model(inputs)
        loss = criterion(outputs, labels)
        loss.backward()
        optimizer.step()
        running_loss += loss.item() * inputs.size(0)

    return running_loss / len(loader.dataset)


def evaluate(model, loader, criterion, device) -> dict:
    """Run the model in eval mode and return a dict of metrics."""
    model.eval()
    running_loss = 0.0
    correct = 0
    total = 0

    with torch.no_grad():
        for inputs, labels in loader:
            inputs, labels = inputs.to(device), labels.to(device)
            outputs  = model(inputs)
            loss     = criterion(outputs, labels)
            running_loss += loss.item() * inputs.size(0)
            _, predicted = outputs.max(1)
            total   += labels.size(0)
            correct += predicted.eq(labels).sum().item()

    results = {"loss": running_loss / total}
    results["accuracy"] = 100.0 * correct / total
    return results


if __name__ == "__main__":
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    print(f"Using device: {device}")

    train_loader, val_loader = get_dataloaders()
    model     = Model().to(device)
    optimizer, criterion = build_optimizer_and_loss(model)

    for epoch in range(3):
        train_loss = train_one_epoch(model, train_loader, optimizer, criterion, device)
        log = f"Epoch {epoch + 1:>3}/{3}  train_loss={train_loss:.4f}"

        if val_loader:
            val_metrics = evaluate(model, val_loader, criterion, device)
            metrics_str = "  ".join(f"val_{k}={v:.4f}" for k, v in val_metrics.items())
            log += f"  {metrics_str}"

        print(log)

    torch.save(model.state_dict(), "weights.pt")
    print("Training complete. Weights saved to weights.pt")